<?php
function mirrorHrmsAttendanceToPos(PDO $hrms, array $att): void {
    try {
        $pos=new PDO('mysql:host='.DB_HOST.';dbname=milk_tea_pos;charset='.DB_CHARSET,DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
        $pos->exec("ALTER TABLE users ADD COLUMN IF NOT EXISTS hrms_user_id INT NULL AFTER lastname");$pos->exec("ALTER TABLE users ADD COLUMN IF NOT EXISTS hrms_employee_id INT NULL AFTER hrms_user_id");
        $pos->exec("CREATE TABLE IF NOT EXISTS staff_attendance(id INT AUTO_INCREMENT PRIMARY KEY,pos_user_id INT NOT NULL,date DATE NOT NULL,time_in TIME NULL,time_out TIME NULL,hours_worked DECIMAL(5,2) NOT NULL DEFAULT 0,late_minutes INT NOT NULL DEFAULT 0,undertime_minutes INT NOT NULL DEFAULT 0,location_status VARCHAR(20) NOT NULL DEFAULT 'unknown',time_in_lat DECIMAL(10,7) NULL,time_in_lon DECIMAL(10,7) NULL,time_out_lat DECIMAL(10,7) NULL,time_out_lon DECIMAL(10,7) NULL,synced_at DATETIME NULL,UNIQUE KEY uq_staff_day(pos_user_id,date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
        foreach(["ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS late_minutes INT NOT NULL DEFAULT 0 AFTER hours_worked","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS undertime_minutes INT NOT NULL DEFAULT 0 AFTER late_minutes","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS location_status VARCHAR(20) NOT NULL DEFAULT 'unknown' AFTER undertime_minutes","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS time_in_lat DECIMAL(10,7) NULL AFTER location_status","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS time_in_lon DECIMAL(10,7) NULL AFTER time_in_lat","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS time_out_lat DECIMAL(10,7) NULL AFTER time_in_lon","ALTER TABLE staff_attendance ADD COLUMN IF NOT EXISTS time_out_lon DECIMAL(10,7) NULL AFTER time_out_lat"] as $sql){try{$pos->exec($sql);}catch(Throwable $e){}}
        $q=$pos->prepare("SELECT id FROM users WHERE hrms_user_id=? OR (? IS NOT NULL AND hrms_employee_id=?) LIMIT 1");$q->execute([(int)($att['user_id']??0),$att['employee_id']??null,$att['employee_id']??null]);$pid=$q->fetchColumn();if(!$pid)return;
        $pos->prepare("INSERT INTO staff_attendance(pos_user_id,date,time_in,time_out,hours_worked,late_minutes,undertime_minutes,location_status,time_in_lat,time_in_lon,time_out_lat,time_out_lon,synced_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE time_in=VALUES(time_in),time_out=VALUES(time_out),hours_worked=VALUES(hours_worked),late_minutes=VALUES(late_minutes),undertime_minutes=VALUES(undertime_minutes),location_status=VALUES(location_status),time_in_lat=VALUES(time_in_lat),time_in_lon=VALUES(time_in_lon),time_out_lat=VALUES(time_out_lat),time_out_lon=VALUES(time_out_lon),synced_at=NOW()")->execute([$pid,$att['date'],$att['time_in'],$att['time_out'],$att['hours_worked']??0,$att['late_minutes']??0,$att['undertime_minutes']??0,$att['location_status']??'unknown',$att['time_in_lat']??null,$att['time_in_lon']??null,$att['time_out_lat']??null,$att['time_out_lon']??null]);
        $hrms->prepare("UPDATE attendance SET pos_user_id=? WHERE id=?")->execute([$pid,$att['id']]);
    } catch(Throwable $e){error_log('HRMS→POS attendance mirror failed: '.$e->getMessage());}
}
